function demoMain(idx,label){
  var models=["resnet50","bert-base","whisper-tiny"];
  var m=models[idx%models.length];
  return "["+label+"] "+m+" inference: batch 8, latency "+(24+idx*5)+"ms, throughput 320/s";
}

